#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <string>\n", argv[0]);
        return 1;
    }

    char *str = argv[1];
    int len = strlen(str);
    int balanced = 1;
    int stack[256] = {0};
    int top = 0;

    for (int i = 0; i < len; i++) {
        char c = str[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {
                balanced = 0;
                break;
            }
            char opening = stack[--top];
            if ((c == ')' && opening != '(') ||
                (c == ']' && opening != '[') ||
                (c == '}' && opening != '{')) {
                balanced = 0;
                break;
            }
        }
    }

    if (top != 0) {
        balanced = 0;
    }

    if (balanced) {
        printf("BALANCED\n");
    } else {
        printf("UNBALANCED\n");
    }

    return 0;
}
